import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './EmployeesPage.css';

export default function EmployeesPage({employees,onAdd,money}) { return <div className="module-page module-page--employees"><PageTitle eyebrow="PEOPLE OPERATIONS" title="Team members" subtitle="Manage your people, roles and monthly base salary records." actions={<button className="btn primary" onClick={onAdd}>＋ Add employee</button>}/><div className="stats-grid"><Stat label="Team size" value={employees.length} change="Firebase employee records" icon="♙" tone="purple" foot="Company workspace roster"/><Stat label="Active members" value={employees.filter(e=>e.status==='Active').length} change="Available roster" icon="✓" tone="green" foot="Status from employee records"/><Stat label="Monthly base payroll" value={money(employees.reduce((s,e)=>s+Number(e.salary||0),0))} change="Before incentives/deductions" icon="₹" tone="blue" foot="Estimate only"/><Stat label="Roles" value={new Set(employees.map(e=>e.role)).size} change="Unique job roles" icon="▦" tone="orange" foot="Role access enforced by UI and Firestore Rules"/></div><div className="panel"><div className="panel-head"><div><h3>Employee directory</h3><p>Role and salary information is shown to Company Owner; employee access is limited.</p></div></div><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>ROLE</th><th>CONTACT</th><th>MONTHLY BASE</th><th>STATUS</th></tr></thead><tbody>{employees.map((e,i)=><tr key={e.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{e.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div><b>{e.name}</b><small>{e.id}</small></div></div></td><td>{e.role}</td><td>{e.email}<small className="cell-sub">{e.phone}</small></td><td>{money(e.salary)}</td><td><Status value={e.status}/></td></tr>)}</tbody></table></div></div></div>; }
